let seriesCache=new WeakMap();let mode='analog';const blank=()=>({version:1,mode,title:'Nové zapojení',components:[],wires:[],probes:[],measurements:[],scopes:2,settings:{duration:mode==='analog'?.01:.1}});
let project=blank(),selected=null,tool='select',placing=null,placementRotation=0,category='Vše',wireStart=null,mouse={x:0,y:0},drag=null,history=[],future=[],record=null,dcPoint=null,logicPreview=null,cursor=0,running=false,busy=false,dirty=true,worker=null,job=0,frame=0,lastFrame=0,lastPaint=0,speed=1,flowMode='current',faultIds=[],scopes=[],inputTimer,liveTimer,toastTimer;
let flowPhase=0;let camera={x:0,y:0,zoom:1},persistTimer,scopeDrag=null,liveOriginal=null;
const svg=$('#schematic'),scene=$('#scene');
function fmt(v,u='',digits=4){if(typeof v==='string')return v;if(!Number.isFinite(v))return '—';if(v===0)return '0'+(u?' '+u:'');const scale=[[1e9,'G'],[1e6,'M'],[1e3,'k'],[1,''],[1e-3,'m'],[1e-6,'µ'],[1e-9,'n'],[1e-12,'p']].find(([s])=>Math.abs(v)>=s)||[1e-15,'f'];return Number((v/scale[0]).toPrecision(digits))+' '+scale[1]+u;}
function number(s){const m=String(s).trim().replace(',','.').match(/^([+-]?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?)\s*(meg|[TGMkmunpµμf]?)(?:\s*(?:Ω|ohm|V|A|F|H|Hz|s|°|%|V\/s))?$/);if(!m)throw Error('Zadejte číslo, například 4.7k, 100n nebo 2m.');const p=m[2],v=Number(m[1])*(p==='meg'?1e6:({T:1e12,G:1e9,M:1e6,k:1e3,m:1e-3,u:1e-6,µ:1e-6,μ:1e-6,n:1e-9,p:1e-12,f:1e-15,'':1}[p]));if(!Number.isFinite(v))throw Error('Hodnota musí být konečná.');return v;}
function toast(msg,error=false){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').className=error?'error':'';$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,error?10000:4000);}
function saveLocal(){clearTimeout(persistTimer);persistTimer=setTimeout(()=>{try{localStorage.setItem(storeKey,JSON.stringify(project));localStorage.setItem(storeKey+'-'+mode,JSON.stringify(project));$('#status').textContent='Uloženo v prohlížeči';}catch{$('#status').textContent='Místní uložení se nezdařilo';}},250);}
function snapshot(){history.push(JSON.stringify(project));if(history.length>80)history.shift();future=[];}
function stop(){running=false;cancelAnimationFrame(frame);$('#run').textContent='Spustit';}
function invalidate(){stop();cancelWorker();record=null;dcPoint=null;cursor=0;dirty=true;faultIds=[];scopes.forEach(s=>{s.start=0;s.follow=true;});previewLogic();saveLocal();render();}
function undo(){if(!history.length)return;future.push(JSON.stringify(project));project=validateProject(JSON.parse(history.pop()));mode=modeOf(project);selected=null;configureMode();invalidate();}
function redo(){if(!future.length)return;history.push(JSON.stringify(project));project=validateProject(JSON.parse(future.pop()));mode=modeOf(project);selected=null;configureMode();invalidate();}
function previewLogic(){logicPreview=null;if(mode!=='analog'&&project.components.length)try{logicPreview=digitalDC({...project,probes:[]});}catch(e){$('#status').textContent=e.message;}}
function bounds(){const points=project.components.flatMap(c=>[...pinsFor(c),{x:c.x-60,y:c.y-60},{x:c.x+100,y:c.y+70}]).concat(project.wires.flatMap(w=>[w.a,w.b]));if(!points.length)return {x:0,y:0,w:900,h:500};const x=Math.min(...points.map(p=>p.x))-30,y=Math.min(...points.map(p=>p.y))-30;return {x,y,w:Math.max(...points.map(p=>p.x))-x+30,h:Math.max(...points.map(p=>p.y))-y+30};}
function applyCamera(){const r=svg.getBoundingClientRect();svg.setAttribute('viewBox',`${camera.x} ${camera.y} ${r.width/camera.zoom} ${r.height/camera.zoom}`);$('#zoom').textContent=Math.round(camera.zoom*100)+' %';}
function fit(){const r=svg.getBoundingClientRect(),b=bounds();camera.zoom=Math.max(.25,Math.min(1.8,r.width/b.w,r.height/b.h));camera.x=b.x-(r.width/camera.zoom-b.w)/2;camera.y=b.y-(r.height/camera.zoom-b.h)/2;applyCamera();}
function world(e){const r=svg.getBoundingClientRect();return {x:camera.x+(e.clientX-r.left)/camera.zoom,y:camera.y+(e.clientY-r.top)/camera.zoom};}
function zoom(factor,at){const r=svg.getBoundingClientRect(),e=at||{clientX:r.left+r.width/2,clientY:r.top+r.height/2},before=world(e);camera.zoom=Math.max(.2,Math.min(4,camera.zoom*factor));const after=world(e);camera.x+=before.x-after.x;camera.y+=before.y-after.y;applyCamera();}
function sampleIndex(time=cursor){if(!record?.time?.length)return 0;let lo=0,hi=record.time.length-1;while(lo<hi){const m=(lo+hi+1)>>1;if(record.time[m]<=time+1e-12)lo=m;else hi=m-1;}return lo;}
function activeData(){return record||logicPreview||dcPoint;}
function valueAt(p){const data=activeData();if(!data||!p)return undefined;const node=data.nodeMap?.[key(p)];return record?data.nodeTraces?.[node]?.[sampleIndex()]:data.logicStates?.[node]??data.voltages?.[node];}
function logicalValue(p){const v=valueAt(p);return v===0||v===1?v:typeof v==='string'?v:'X';}
function current(c){if(record)return record.traces?.find(t=>t.id==='I:'+c.id)?.values[sampleIndex()];return dcPoint?.currents?.[c.id];}
function wireCurrentMap(){const map=new Map();if(mode!=='analog')return map;const adj=new Map(),ws=project.wires;for(const w of ws)for(const end of ['a','b']){let k=key(w[end]);if(!adj.has(k))adj.set(k,[]);adj.get(k).push({w,end});}const terms=new Set(project.components.flatMap(c=>pinsFor(c).map(key)));for(const c of project.components){const ps=pinsFor(c),v=current(c);if(ps.length!==2||!Number.isFinite(v)||Math.abs(v)<1e-14)continue;for(let side=0;side<2;side++){let pos=key(ps[side]),seen=new Set(),i=side===0?-v:v;for(let n=0;n<ws.length;n++){const next=(adj.get(pos)||[]).filter(a=>!seen.has(a.w.id));if(next.length!==1)break;const {w,end}=next[0];seen.add(w.id);map.set(w.id,end==='a'?i:-i);pos=key(w[end==='a'?'b':'a']);if(terms.has(pos))break;}}}return map;}
function wireColor(p){if(mode!=='analog'){let v=logicalValue(p);return v===1?'var(--on)':v===0?'var(--wire)':'#c191df';}const v=valueAt(p);if(!Number.isFinite(v)||Math.abs(v)<1e-8)return 'var(--wire)';return v>0?'#36b68d':'#ef8496';}
function path(points){return points.map((p,i)=>(i?'L':'M')+p.x+' '+p.y).join('');}
function renderScene(){const routes=connections(project),flows=wireCurrentMap();let out='';for(const r of routes){const picked=selected?.kind==='wire'&&r.ids.includes(selected.id);out+=`<g class="connection ${picked?'selected':''}" data-wire="${esc(r.id)}">`;for(let i=0;i<r.ids.length;i++){const w=project.wires.find(w=>w.id===r.ids[i]);const d=path([w.a,w.b]),v=flows.get(w.id);out+=`<path class="wire-hit" data-segment="${esc(w.id)}" d="${d}"/><path class="wire" d="${d}" style="stroke:${wireColor(w.a)}"/>`;if(flowMode!=='none'&&Number.isFinite(v)&&Math.abs(v)>1e-14){const phase=flowPhase*(v<0?-1:1)*(flowMode==='electrons'?-1:1);out+=`<path class="flow" d="${d}" style="stroke-dashoffset:${-phase}"/>`;}}if(picked)for(const [end,p]of [['a',r.points[0]],['b',r.points.at(-1)]])out+=`<circle class="wire-handle" data-end="${end}" data-wire="${esc(r.id)}" cx="${p.x}" cy="${p.y}" r="7"/>`;out+='</g>';}
const counts=new Map();for(const w of project.wires)for(const p of [w.a,w.b])counts.set(key(p),(counts.get(key(p))||0)+1);for(const c of project.components)for(const p of pinsFor(c))counts.set(key(p),(counts.get(key(p))||0)+1);for(const [k,n]of counts)if(n>=3){let [x,y]=k.split(',');out+=`<circle class="junction" cx="${x}" cy="${y}" r="4"/>`;}
for(const c of project.components){const ps=pinsFor(c),picked=selected?.kind==='component'&&selected.id===c.id,h=meta(c.type)?.pins.reduce((h,p)=>Math.max(h,Math.abs(p.y)+15),40)||40,vertical=(c.rotation||0)%180!==0,lx=vertical?48:0,ly=vertical?-17:-h-10,vy=vertical?4:h+14;out+=`<g class="component ${picked?'selected':''} ${faultIds.includes(c.id)?'fault':''}" data-component="${esc(c.id)}" transform="translate(${c.x} ${c.y})"><g transform="rotate(${c.rotation||0})"><rect class="hit-part" x="-30" y="${-Math.max(20,h-10)}" width="60" height="${Math.max(40,h*2-20)}"/>${symbol(c.type,c)}</g><text class="component-label" x="${c.type==='gnd'?25:lx}" y="${c.type==='gnd'?20:ly}" text-anchor="${vertical||c.type==='gnd'?'start':'middle'}">${esc(c.params.label||c.id)}</text>`;if(mode==='analog'&&c.type!=='gnd'){const unit=({resistor:'Ω',capacitor:'F',inductor:'H',vdc:'V',vac:'V',idc:'A',iac:'A'})[c.type],text=c.type==='opamp'?'OZ':c.type==='switch'?(c.params.closed?'ON':'OFF'):unit?fmt(c.params.value,unit):meta(c.type)?.label||'';out+=`<text class="component-value" x="${lx}" y="${vy}" text-anchor="${vertical?'start':'middle'}">${esc(text)}</text>`;}out+='</g>';
for(const p of ps){out+=`<circle class="pin" data-pin="${esc(c.id)}:${p.id}" data-x="${p.x}" data-y="${p.y}" cx="${p.x}" cy="${p.y}" r="4"><title>${esc(c.id)} · ${esc(p.id)}</title></circle>`;if(c.type==='opamp'){const labels={plus:'+',minus:'−',out:'OUT',vcc:'V+ napájení',vee:'V− napájení'};out+=`<text class="pin-label" x="${p.x+8}" y="${p.y-9}">${labels[p.id]}</text>`;}if(mode!=='analog'&&((p.x>=c.x&&c.type!=='output')||c.type==='output')){const v=logicalValue(p),x=c.type==='output'?c.x:p.x+21,y=c.type==='output'?c.y:p.y;out+=`<g class="logic-value" data-logic="${esc(c.id)}:${p.id}"><rect class="logic-badge ${v===1?'high':v===0?'low':''}" x="${x-12}" y="${y-11}" width="24" height="22" rx="3"/><text class="logic-text ${v===1?'high':''}" x="${x}" y="${y+5}">${v}</text></g>`;}}
}
scene.innerHTML=out;$('#emptyHint').hidden=project.components.length>0;$('#stats').textContent=`${project.components.length} prvků · ${routes.length} propojení`;renderPreview();}
function renderPreview(){let out='';if(placing)out=`<g opacity=".65" transform="translate(${snap(mouse.x)} ${snap(mouse.y)}) rotate(${placementRotation})">${symbol(placing,{rotation:placementRotation,params:meta(placing).defaults})}</g>`;if(wireStart)out+=`<path class="pending" d="${path(orthogonalPath(wireStart,{x:snap(mouse.x),y:snap(mouse.y)}))}"/>`;$('#preview').innerHTML=out;$('#cancel').hidden=!wireStart&&!placing;}
function renderLibrary(){let available=catalog.filter(c=>allowed(c.type,mode));$('#categories').innerHTML=['Vše',...new Set(available.map(c=>c.category))].map(c=>`<button data-category="${esc(c)}" class="${c===category?'active':''}">${esc(c)}</button>`).join('');const q=$('#search').value.toLocaleLowerCase('cs');$('#parts').innerHTML=available.filter(c=>(category==='Vše'||c.category===category)&&`${c.label} ${c.type}`.toLocaleLowerCase('cs').includes(q)).map(c=>`<button class="part ${placing===c.type?'active':''}" data-part="${c.type}"><svg viewBox="-45 -35 90 70" aria-hidden="true">${symbol(c.type,{params:c.defaults})}</svg><span>${esc(c.label)}</span></button>`).join('');let last='';$('#examples').innerHTML=examples.filter(e=>e.mode===mode).map(e=>{let group=e.group!==last?`<h3>${esc(e.group)}</h3>`:'';last=e.group;return group+`<button data-example="${esc(e.id)}">${esc(e.title)}<small>${esc(e.description)}</small></button>`;}).join('');}
const paramLabels={value:'Hodnota',frequency:'Frekvence f [Hz]',offset:'Stejnosměrná složka [V]',phase:'Počáteční fáze φ [°]',duty:'Střída D [0–1]',initialVoltage:'Počáteční napětí [V]',initialCurrent:'Počáteční proud [A]',gain:'Otevřené zesílení A',rail:'Vnitřní meze ± [V]',slew:'Rychlost přeběhu [V/s]',gbw:'Součin zesílení a pásma [Hz]',n:'Emisní koeficient n',breakdown:'Průrazné napětí [V]',rz:'Dynamický odpor [Ω]',peakCurrent:'Špičkový proud [A]',peakVoltage:'Špičkové napětí [V]',valleyCurrent:'Údolní proud [A]',valleyVoltage:'Údolní napětí [V]',preset:'Čas PT [s]',initial:'Počáteční stav',closed:'Sepnuto',powered:'Vnější napájení V+ / V−'};
function measurementName(m){return m.kind==='current'?`I(${m.componentId})`:m.kind==='logic'?`${m.componentId} · ${m.pin||'OUT'}`:`U(${m.componentId})`;}
function field(label,k,value){return `<label class="field"><span>${esc(label)}</span><input data-param="${k}" value="${esc(value)}" inputmode="decimal"></label>`;}
function renderProperties(){const el=$('#properties'),c=project.components.find(c=>selected?.kind==='component'&&c.id===selected.id);$('#rotate').disabled=!c||mode!=='analog';$('#delete').disabled=!selected;$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;
if(c){let params={...meta(c.type).defaults,...c.params};$('#propertyTitle').textContent=c.id+' · '+meta(c.type).label;let out='';if(c.type==='input')out+=`<div class="logic-switch"><button data-input="0" class="${!params.value?'active':''}">0 · OFF</button><button data-input="1" class="${params.value?'active':''}">1 · ON</button></div>`;
if(mode!=='analog'){out+='<div class="pin-values">'+pinsFor(c).map(p=>`<span>${esc(p.id)}</span><b data-read-pin="${esc(c.id)}:${p.id}">${logicalValue(p)}</b>`).join('')+'</div>';}
out+=field('Označení','label',c.params.label||c.id);
for(const [k,v]of Object.entries(params)){if(k==='label'||(c.type==='input'&&k==='value')||(k==='powered'&&c.type==='opamp')||(c.type==='opamp'&&params.powered&&k==='rail'))continue;if(k==='value'&&['diode','led','zener','schottky','tunnel'].includes(c.type)){out+=field('Saturační proud Is [A]',k,v);continue;}if(k==='waveform'){out+=`<label class="field"><span>Průběh</span><select data-param="waveform">${[['sine','Sinus'],['square','Obdélník'],['triangle','Trojúhelník']].map(([v2,l])=>`<option value="${v2}" ${v===v2?'selected':''}>${l}</option>`).join('')}</select></label>`;continue;}if(typeof v==='boolean'){out+=`<label class="field"><span>${paramLabels[k]||k}</span><select data-param="${k}"><option value="true" ${v?'selected':''}>Ano</option><option value="false" ${!v?'selected':''}>Ne</option></select></label>`;continue;}if(typeof v!=='number')continue;let label=k==='value'?({resistor:'Odpor R [Ω]',capacitor:'Kapacita C [F]',inductor:'Indukčnost L [H]',vdc:'Napětí U [V]',vac:'Amplituda Umax [V]',idc:'Proud I [A]',iac:'Amplituda Imax [A]',switch:'Odpor sepnutí [Ω]'})[c.type]||paramLabels[k]:k==='offset'&&c.type==='iac'?'Stejnosměrná složka [A]':paramLabels[k]||k;out+=field(label,k,v);if(k==='frequency'){out+=`<label class="field dual"><span>Frekvence</span><input data-live="frequency" type="range" min="-1" max="8" step=".01" value="${Math.log10(v)}" aria-label="Slider frekvence"><output data-live-output="frequency">${fmt(v,'Hz')}</output></label>`+field('Perioda T [s]','period',1/v);}if(k==='phase')out+=`<label class="field dual"><span>Fázový posun</span><input data-live="phase" type="range" min="-180" max="180" step="1" value="${v}" aria-label="Slider fáze"><output data-live-output="phase">${v}°</output></label>`;}
if(c.type==='opamp')out+='<p class="muted">V+ je kladné a V− záporné napájení. Oba vývody zapojte ke zdrojům. + a − vlevo jsou signálové vstupy, OUT je výstup.</p>';
if(mode==='analog'&&c.type!=='gnd')out+=`<section class="measure-picker"><h3>Měřit na ${esc(c.id)}</h3><label class="field"><span>Veličina</span><select id="measureKind"><option value="voltage">Napětí mezi vývody [V]</option><option value="current">Proud součástkou [A]</option></select></label><label class="field"><span>Cílový osciloskop</span><select id="measureTarget">${Array.from({length:project.scopes},(_,i)=>`<option value="${i}">Osciloskop ${i+1}</option>`).join('')}<option value="new">Nový osciloskop</option></select></label><button id="addMeasurement" class="primary">Přidat měření</button><p class="muted">${c.type==='opamp'?'Napětí OUT vůči zemi; proud výstupního vývodu.':'U = V(a) − V(b). Kladný proud teče a → b.'}</p></section>`;
if(mode!=='analog')out+=`<button id="logicToScope">Časový průběh výstupu</button>`;
out+=`<div class="actions"><button id="duplicate">Duplikovat</button>${mode==='analog'?'<button id="rotateSelected">Otočit</button>':''}<button id="deleteSelected">Smazat</button></div>`;el.innerHTML=out;
}else if(selected?.kind==='wire'){$('#propertyTitle').textContent='Propojení';el.innerHTML='<p class="muted">Koncové body přetáhněte na jiný vývod. Tažením čáry posunete úsek. Spojené vývody zůstávají připojené.</p><button id="deleteSelected">Smazat propojení</button>';}
else{$('#propertyTitle').textContent='Vlastnosti';el.innerHTML='<p class="muted">Vyberte součástku ve schématu.</p>';}
renderMeasurementList();}
function renderMeasurementList(){const el=$('#measurements');el.innerHTML='<h3>Měření</h3>'+(project.measurements.length?project.measurements.map(m=>`<div class="measurement"><span style="color:${m.color}">${esc(measurementName(m))}<small>Osciloskop ${m.scope+1}</small></span><output data-measure-value="${esc(m.id)}">${esc(fmt(sampleMeasurement(project,m,activeData(),sampleIndex()),measurementUnit(m)))}</output><button data-remove-measure="${esc(m.id)}" aria-label="Odstranit ${esc(measurementName(m))}">×</button></div>`).join(''):'<p class="muted">'+(mode==='analog'?'Měření přidáte u vybrané součástky.':'Stavy 0/1 jsou přímo u výstupů. Osciloskop je volitelný.')+'</p>');}
function updateReadouts(){for(const b of $$('[data-read-pin]')){const [id,pin]=b.dataset.readPin.split(':'),c=project.components.find(c=>c.id===id),p=c&&pinsFor(c).find(p=>p.id===pin);b.textContent=p?logicalValue(p):'X';}for(const el of $$('[data-measure-value]')){let m=project.measurements.find(m=>m.id===el.dataset.measureValue);if(m)el.textContent=fmt(sampleMeasurement(project,m,activeData(),sampleIndex()),measurementUnit(m));}$('#time').textContent='t = '+fmt(record?.time?.[sampleIndex()]??0,'s',7);$('#timeline').max=record?.time?.length?record.time.length-1:1;$('#timeline').value=sampleIndex();$('#timeScale').textContent=record?`1 s přehrávání = ${fmt((record.time.at(-1)-record.time[0])/10*speed,'s',3)} děje`:'';}
function render(){renderScene();renderProperties();renderScopes();$('#title').value=project.title;$('#duration').value=project.settings.duration;updateReadouts();}
function ensureScopes(){while(scopes.length<project.scopes)scopes.push({start:0,span:project.settings.duration/2,follow:true,yScale:1});scopes.length=project.scopes;const host=$('#scopes');if(host.children.length!==project.scopes){host.innerHTML=Array.from({length:project.scopes},(_,i)=>`<article class="scope" data-scope="${i}"><header><strong>Osciloskop ${i+1}</strong><output id="scopeValue${i}"></output><button data-scope-action="out" data-scope="${i}" title="Oddálit čas">−</button><button data-scope-action="in" data-scope="${i}" title="Přiblížit čas">+</button><button data-scope-action="fit" data-scope="${i}" title="Celý záznam">Celý</button><button data-scope-action="yout" data-scope="${i}" title="Zmenšit svislé měřítko">Y−</button><button data-scope-action="yin" data-scope="${i}" title="Zvětšit svislé měřítko">Y+</button></header><div class="scope-chart" data-scope="${i}" id="scopeChart${i}"></div><div class="scope-legend" id="scopeLegend${i}"></div></article>`).join('');}}
// Preserve narrow spikes and every logic transition while decimating only the
// visible time interval. A one-sample zoom always retains its actual samples.

function renderScopes(){ensureScopes();for(let i=0;i<project.scopes;i++){const chart=$('#scopeChart'+i),ms=project.measurements.filter(m=>m.scope===i),s=scopes[i];$('#scopeLegend'+i).innerHTML=ms.map(m=>`<span style="color:${m.color}">${esc(measurementName(m))} <b>${esc(fmt(sampleMeasurement(project,m,activeData(),sampleIndex()),measurementUnit(m)))}</b></span>`).join('');if(!ms.length){chart.innerHTML='<div class="scope-empty">Vyberte součástku → veličinu → tento osciloskop.</div>';continue;}if(!record?.time?.length){chart.innerHTML='<div class="scope-empty">'+(mode==='analog'?'Spusťte záznam.':'Stavy jsou přímo ve schématu. Spusťte záznam pro časový průběh.')+'</div>';continue;}
const duration=record.time.at(-1),W=650,H=190,L=68,R=15,T=12,B=28,PW=W-L-R,PH=H-T-B;let span=Math.max(record.step||1e-9,Math.min(duration,s.span||duration));if(s.follow&&cursor>s.start+span)s.start=cursor-span;s.start=Math.max(0,Math.min(duration-span,s.start));const start=s.start,end=start+span,x=t=>L+(t-start)/span*PW;if(!seriesCache.has(record))seriesCache.set(record,new Map());const cache=seriesCache.get(record);const traces=ms.map(m=>{if(!cache.has(m.id))cache.set(m.id,measurementSeries(project,m,record));return {m,values:cache.get(m.id)};});const logic=ms[0].kind==='logic',unit=measurementUnit(ms[0]);let min=Infinity,max=-Infinity;for(const tr of traces)for(const v of tr.values)if(Number.isFinite(v)){min=Math.min(min,v);max=Math.max(max,v);}if(min===Infinity){chart.innerHTML='<div class="scope-empty">X / Z · neurčený nebo odpojený signál</div>';continue;}if(logic){min=-.2;max=1.2;}else{const pad=(max-min)*.12||Math.max(Math.abs(max)*.2,unit==='A'?1e-6:.1);min-=pad;max+=pad;const mid=(max+min)/2,range=(max-min)/s.yScale;min=mid-range/2;max=mid+range/2;}const y=v=>T+(max-v)/(max-min)*PH;
let out=`<defs><clipPath id="clip${i}"><rect x="${L}" y="${T}" width="${PW}" height="${PH}"/></clipPath></defs>`;for(let n=0;n<=4;n++){let py=T+n*PH/4,v=max-n*(max-min)/4;out+=`<line class="plot-grid" x1="${L}" y1="${py}" x2="${W-R}" y2="${py}"/><text x="${L-7}" y="${py+4}" text-anchor="end">${esc(fmt(v,unit,3))}</text>`;}for(let n=0;n<=5;n++){let px=L+n*PW/5,t=start+n*span/5;out+=`<line class="plot-grid" x1="${px}" y1="${T}" x2="${px}" y2="${H-B}"/><text x="${px}" y="${H-8}" text-anchor="middle">${esc(fmt(t,'s',3))}</text>`;}
for(const {m,values}of traces){let d='',prev=null;const indices=scopeSampleIndices(record.time,values,start,end,cursor,PW,logic);for(const j of indices){const t=record.time[j],v=values[j];if(!Number.isFinite(v)){prev=null;continue;}if(prev===null)d+='M'+x(t).toFixed(2)+' '+y(v).toFixed(2);else if(logic)d+='H'+x(t).toFixed(2)+'V'+y(v).toFixed(2);else d+='L'+x(t).toFixed(2)+' '+y(v).toFixed(2);prev=v;}out+=`<path class="trace" clip-path="url(#clip${i})" stroke="${m.color}" d="${d}"/>`;}
let xp=x(record.time[sampleIndex()]);if(xp>=L&&xp<=W-R)out+=`<line x1="${xp}" x2="${xp}" y1="${T}" y2="${H-B}" stroke="var(--muted)" stroke-dasharray="3 3" opacity=".6"/>`;chart.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-label="${esc(ms.map(measurementName).join(', '))}">${out}</svg>`;$('#scopeValue'+i).textContent=unit||'0 / 1';}}
function addMeasurement(kind,componentId,target,pin){const unit=kind==='current'?'A':kind==='logic'?'':'V';let scope=target==='new'?project.scopes:Number(target)||0;const existing=project.measurements.find(m=>m.scope===scope);if(existing&&measurementUnit(existing)!==unit){scope=project.scopes;toast('Jiná jednotka dostala vlastní osciloskop.');}if(scope>=4){toast('Jsou k dispozici čtyři osciloskopy. Odstraňte některé měření.',true);return;}if(project.measurements.some(m=>m.kind===kind&&m.componentId===componentId&&m.pin===pin&&m.scope===scope))return; snapshot();project.scopes=Math.max(project.scopes,scope+1);project.measurements.push({id:uid('m'),kind,componentId,scope,pin,color:colors[project.measurements.length%colors.length]});saveLocal();renderMeasurementList();renderScopes();}
function cancelWorker(){if(worker){worker.terminate();worker=null;}job++;busy=false;}
function solve(payload){cancelWorker();const id=job;busy=true;$('#run').textContent='Zastavit výpočet';$('#status').textContent='Počítám zapojení…';return new Promise((resolve,reject)=>{worker=new Worker(new URL('./solver-worker.mjs',import.meta.url),{type:'module'});worker.onmessage=({data})=>{if(data.id!==id)return;busy=false;worker.terminate();worker=null;if(data.error)reject(Error(data.error));else resolve(data.result);};worker.onerror=e=>{busy=false;worker?.terminate();worker=null;reject(Error(e.message||'Výpočetní jádro se nenačetlo.'));};worker.postMessage({...payload,id});});}
function currentState(){if(!record)return null;if(mode!=='analog')return record.states?.[sampleIndex()]||null;const idx=sampleIndex(),model=compile({...project,probes:[]}),parts={};for(const p of model.parts){const v=n=>n==='0'?0:record.nodeTraces[record.nodeMap[key(p.pins.find(pin=>p.nodes[pin.id]===n)||p.pins[0])]]?.[idx]??0;const ps=pinsFor(p),at=pin=>{const point=ps.find(p=>p.id===pin);return point?record.nodeTraces[record.nodeMap[key(point)]]?.[idx]??0:0;};parts[p.id]={v:p.type==='opamp'?at('out'):at('a')-at('b'),i:record.traces.find(t=>t.id==='I:'+p.id)?.values[idx]||0};}return {parts};}
function mergeRecord(old,tail,cut){const idx=sampleIndex(cut),time=old.time.slice(0,idx+1).concat(tail.time.slice(1)),traces=tail.traces.map(tr=>({...tr,values:(old.traces.find(t=>t.id===tr.id)?.values.slice(0,idx+1)||Array(idx+1).fill(NaN)).concat(tr.values.slice(1))})),nodeTraces=Object.fromEntries(Object.entries(tail.nodeTraces).map(([node,values])=>[node,(old.nodeTraces[node]?.slice(0,idx+1)||Array(idx+1).fill(NaN)).concat(values.slice(1))]));return {...tail,time,traces,nodeTraces,...(tail.states?{states:(old.states?.slice(0,idx+1)||[]).concat(tail.states.slice(1))}:{})};}
async function compute({resume=true,preserve=false,state=null}={}){if(!project.components.length)return toast('Přidejte součástky nebo otevřete ukázku.');stop();const old=record,at=record?.time?.[sampleIndex()]||0;try{const settings=automaticSettings(project),p={...copy(project),probes:[],settings};let next;if(preserve&&old&&state&&at>0&&at<settings.duration){next=await solve({mode:'tran',project:p,options:{duration:settings.duration-at,step:settings.step,startTime:at,initialState:state}});next=mergeRecord(old,next,at);}else{const bundle=await solve({mode:'bundle',project:p,options:{analysis:'scope',settings}});next=bundle.analysis;dcPoint=bundle.dc;}record=next;dirty=false;cursor=preserve?Math.min(at,record.time.at(-1)):0;faultIds=[];$('#run').textContent='Spustit';$('#status').textContent='Záznam připraven';renderScene();renderScopes();renderMeasurementList();updateReadouts();if(resume)play();}catch(e){$('#run').textContent='Spustit';faultIds=project.components.filter(c=>e.message.includes(c.id)).map(c=>c.id);$('#status').textContent=e.message;renderScene();toast(e.message,true);}}
function play(){if(!record?.time?.length)return;if(cursor>=record.time.at(-1)-1e-12){toast('Konec záznamu. Pro nový děj zvolte Od začátku.');return;}running=true;lastFrame=performance.now();lastPaint=0;$('#run').textContent='Pozastavit';function tick(now){if(!running)return;const elapsed=(now-lastFrame)/1000,last=record.time.at(-1);lastFrame=now;flowPhase=(flowPhase+elapsed*40*speed)%16;cursor=Math.min(last,cursor+elapsed*(last-record.time[0])/10*speed);if(now-lastPaint>45||cursor>=last){lastPaint=now;renderScene();renderScopes();updateReadouts();}if(cursor>=last){stop();$('#status').textContent='Konec záznamu';return;}frame=requestAnimationFrame(tick);}frame=requestAnimationFrame(tick);}
async function run(){if(busy){cancelWorker();$('#run').textContent='Spustit';$('#status').textContent='Výpočet zastaven';return;}if(running){stop();cursor=record.time[sampleIndex()];renderScene();renderScopes();updateReadouts();return;}if(dirty||!record)return compute();play();}
function step(delta){stop();if(!record)return toast('Nejprve spusťte záznam.');let idx=Math.max(0,Math.min(record.time.length-1,sampleIndex()+delta));cursor=record.time[idx];scopes.forEach(s=>s.follow=true);renderScene();renderScopes();updateReadouts();}
