function nextId(type){const prefix=({resistor:'R',capacitor:'C',inductor:'L',vdc:'V',vac:'V',idc:'I',iac:'I',gnd:'GND',diode:'D',led:'LED',zener:'ZD',schottky:'SD',opamp:'U',input:'IN',output:'OUT',switch:'S'})[type]||type.toUpperCase();let i=1;while(project.components.some(c=>c.id===prefix+i))i++;return prefix+i;}
function splitAt(p){let next=[];for(const w of project.wires){const on=(w.a.x===w.b.x&&p.x===w.a.x&&p.y>Math.min(w.a.y,w.b.y)&&p.y<Math.max(w.a.y,w.b.y))||(w.a.y===w.b.y&&p.y===w.a.y&&p.x>Math.min(w.a.x,w.b.x)&&p.x<Math.max(w.a.x,w.b.x));if(on)next.push({...w,b:{...p}},{id:uid(),a:{...p},b:{...w.b}});else next.push(w);}project.wires=next;}
